import { BinaryObject } from "@amodx/binary";
export async function compressBinaryObject(object) {
    const compressedArrayBuffer = await new Response(new Blob([BinaryObject.objectToBuffer(object)])
        .stream()
        .pipeThrough(new CompressionStream("gzip"))).arrayBuffer();
    return compressedArrayBuffer;
}
export async function expandBinaryObject(buffer, useSharedMemory = false) {
    const decompressedBuffer = await new Response(new Blob([buffer]).stream().pipeThrough(new DecompressionStream("gzip"))).arrayBuffer();
    BinaryObject.setUseSharedMemory(useSharedMemory);
    const object = BinaryObject.bufferToObject(decompressedBuffer);
    BinaryObject.setUseSharedMemory(false);
    return object;
}
